INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·乾祐三年正月奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/jiuwudaishi-103-january-950-reports/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年正月奏报，段落 jiu-wudaishi-205deb4a7860-p002483；已核上下文及传主，纸本及异文待核。", "id": "79349ac2-c735-5498-aa2f-079985404fc6"}, {"title": "宋史·卷483·留从效传·兄留从愿", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/songshi-483-liu-congyuan-identity/source.txt", "note": "《宋史》卷483·留从效传·兄留从愿，段落 songshi-9c6e46fee832-p075234；已核上下文及传主，纸本及异文待核。", "id": "c590911e-e177-57bf-85d3-242065c78fa4"}, {"title": "宋史·卷483·留从效传·清源军设置", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/songshi-483-qingyuan-establishment/source.txt", "note": "《宋史》卷483·留从效传·清源军设置，段落 songshi-9c6e46fee832-p075230；已核上下文及传主，纸本及异文待核。", "id": "d1ab70fb-fe99-506e-90a1-3746d3511de8"}, {"title": "资治通鉴·卷288·乾祐二年·十二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/tongjian-288-949-year-end/source.txt", "note": "《资治通鉴》卷288·乾祐二年·十二月及追述，段落 zizhi-tongjian-a63549944a71-p003426；已核上下文及传主，纸本及异文待核。", "id": "59b9656d-4231-5681-a4d0-82c751473012"}, {"title": "新五代史·卷53·王景崇传·凤翔城破", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/xinwudaishi-053-fengxiang-fall/source.txt", "note": "《新五代史》卷53·王景崇传·凤翔城破，段落 xin-wudaishi-b08f244b9241-p002068；已核上下文及传主，纸本及异文待核。", "id": "4a32b468-e17a-5f6d-b2d8-7d74d9276cfc"}, {"title": "旧五代史·卷一百〇七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b9977b40cd7afc61ddc81473948ffdd463d53ee9/content/books/zizhi-tongjian/vol-288/year-0948/part-03/sources/library/jiuwudaishi-107-yang-bin-power/source.txt", "note": "《旧五代史》卷一百〇七，段落 jiu-wudaishi-205deb4a7860-p002563；EPUB电子本，纸本及异文待核", "id": "53cb4f0b-1a28-539d-8d25-5a743f2bde5b"}, {"title": "新五代史·卷68·闽世家·王氏灭亡纪年说明", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-068-fall-year/source.txt", "note": "《新五代史》卷68·闽世家·王氏灭亡纪年说明，段落 xin-wudaishi-b08f244b9241-p003415；已核卷号与传主，电子本及异文待纸本校核。", "id": "af3458df-4cef-5654-8b54-5a0ab901bec3"}]'::jsonb)
