INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "周璨", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "邢州人，曾任诸卫将军，失去官职后跟随王景崇西行，成为谋士。949年凤翔战事末期劝王景崇投降，王景崇自焚后也投降。生卒年未载。", "biography": null, "status": "draft", "id": "e095759e-4e79-59e5-a5b0-7527f74e5dfb"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "公孙辇", "aliases": ["公孫輦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王景崇的将领。949年十二月按计划烧凤翔东门诈降，得知王景崇已自焚后投降赵晖。《新五代史》也记此事。生卒年未载。", "biography": null, "status": "draft", "id": "d855adaf-1edd-5643-a1f7-1d1658a3c852"}, {"name": "张思练", "aliases": ["張思練"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王景崇的将领。949年十二月与公孙辇烧凤翔东门诈降，派人察看府署后得知王景崇已自焚。生卒年及随后是否正式受降未载。", "biography": null, "status": "draft", "id": "9c9bb20a-8b35-5e21-8a20-235f4df2aa77"}, {"name": "王万敢", "aliases": ["王萬敢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉密州刺史。949年十二月攻击南唐海州获水镇；《旧五代史》次年正月也载他在海州方向的奏报，镇名作荻水，地名及是否同次行动仍待校核。生卒年未载。", "biography": null, "status": "draft", "id": "0e0fb3d0-08be-5b24-8bc6-9cb76e19259a"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "留从愿", "aliases": ["留從願"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "留从效的兄长。949年《通鉴》记他毒杀董思安并接任刺史，职名前地名写南州，尚待校核。《宋史》留从效传也明记有兄从愿。生卒年未载。", "biography": null, "status": "draft", "id": "b04c04f4-78dd-5966-83c8-2e1332bb55ca"}, {"name": "董思安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年参与反朱文进的谋议和泉州政变，后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "385e66d6-1650-5db4-a215-4208ca968420"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

